//! Support for code generated by `ras-jsonrpc-bidirectional-macro`.
//!
//! Not public API. The generated server code names its dependencies through this module, so an
//! API crate needs only this crate and `serde` for its own derives. Anything here may change in
//! any release.

use crate::{ServerError, ServerResult};
use ras_jsonrpc_bidirectional_types::{
    BidirectionalError, BidirectionalMessage, ConnectionId, ConnectionManager, ServerNotification,
};
use ras_jsonrpc_types::{HandlerErrorOutcome, JsonRpcRequest, JsonRpcResponse};
use serde::{Serialize, de::DeserializeOwned};
use serde_json::Value;
use std::time::Duration;

pub use async_trait;
pub use ras_auth_core;
pub use ras_jsonrpc_bidirectional_types;
pub use ras_jsonrpc_types;
pub use serde_json;

/// Decode a request's params into the method's request type.
///
/// Missing params decode from `null`, so a method taking `()` accepts a request without params.
/// A decode failure is [`ServerError::InvalidParams`], which the client receives as `-32602`.
pub fn decode_params<T: DeserializeOwned>(params: Option<Value>) -> ServerResult<T> {
    serde_json::from_value(params.unwrap_or(Value::Null))
        .map_err(|e| ServerError::InvalidParams(e.to_string()))
}

/// Turn a handler's return value into the response to the request with `id`.
pub fn handler_response<R: Serialize>(
    id: Option<Value>,
    result: Result<R, Box<dyn std::error::Error + Send + Sync>>,
) -> ServerResult<Option<JsonRpcResponse>> {
    match result {
        Ok(value) => {
            let value =
                serde_json::to_value(value).map_err(|e| ServerError::Internal(e.to_string()))?;
            Ok(Some(JsonRpcResponse::success(value, id)))
        }
        Err(error) => Err(
            match HandlerErrorOutcome::from_handler_error(error.as_ref()) {
                HandlerErrorOutcome::Public(error) => ServerError::Rpc(error),
                HandlerErrorOutcome::ReservedCode(code) => ServerError::Internal(format!(
                    "handler returned a PublicRpcError with reserved code {code}"
                )),
                _ => ServerError::Internal(error.to_string()),
            },
        ),
    }
}

/// Send the notification `method` with `params` to one connection.
pub async fn send_notification<P: Serialize>(
    manager: &dyn ConnectionManager,
    connection_id: ConnectionId,
    method: &str,
    params: P,
) -> ras_jsonrpc_bidirectional_types::Result<()> {
    let notification = ServerNotification {
        method: method.to_string(),
        params: serde_json::to_value(params)?,
        metadata: None,
    };
    manager
        .send_to_connection(
            connection_id,
            BidirectionalMessage::ServerNotification(notification),
        )
        .await
}

/// Call `method` on one client and wait up to `timeout` for its answer.
///
/// The pending request is removed again when sending fails or the call times out, so an
/// unanswered call leaves nothing behind in the connection manager.
pub async fn call_client<P: Serialize, R: DeserializeOwned>(
    manager: &dyn ConnectionManager,
    connection_id: ConnectionId,
    method: &str,
    params: P,
    timeout: Duration,
) -> Result<R, BidirectionalError> {
    let request_id = Value::String(uuid::Uuid::new_v4().to_string());
    let request = JsonRpcRequest {
        jsonrpc: "2.0".to_string(),
        method: method.to_string(),
        params: Some(serde_json::to_value(params)?),
        id: Some(request_id.clone()),
    };

    let (response_sender, response_receiver) = tokio::sync::oneshot::channel();
    manager
        .register_pending_request(connection_id, request_id.clone(), response_sender)
        .await
        .map_err(|_| {
            BidirectionalError::ConnectionError("Failed to register pending request".to_string())
        })?;

    if let Err(e) = manager
        .send_to_connection(connection_id, BidirectionalMessage::Request(request))
        .await
    {
        let _ = manager
            .remove_pending_request(connection_id, &request_id)
            .await;
        return Err(e);
    }

    let response = match tokio::time::timeout(timeout, response_receiver).await {
        Ok(Ok(response)) => response,
        Ok(Err(_)) => {
            return Err(BidirectionalError::ConnectionError(
                "Response channel closed".to_string(),
            ));
        }
        Err(_) => {
            let _ = manager
                .remove_pending_request(connection_id, &request_id)
                .await;
            return Err(BidirectionalError::Timeout);
        }
    };

    if let Some(error) = response.error {
        return Err(BidirectionalError::RpcError(error.message));
    }
    let result = response
        .result
        .ok_or_else(|| BidirectionalError::InvalidResponse("Missing result".to_string()))?;
    Ok(serde_json::from_value(result)?)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::DefaultConnectionManager;
    use crate::connection::ChannelMessageSender;
    use ras_jsonrpc_bidirectional_types::ConnectionInfo;

    #[test]
    fn decode_failure_is_invalid_params() {
        let error = decode_params::<u32>(Some(serde_json::json!("not a number"))).unwrap_err();
        assert!(matches!(error, ServerError::InvalidParams(_)));
        // A missing payload decodes from null, which suits `()`.
        decode_params::<()>(None).unwrap();
    }

    #[tokio::test]
    async fn timed_out_call_removes_its_pending_request() {
        let manager = DefaultConnectionManager::new();
        let id = ConnectionId::new();
        let (tx, mut rx) = tokio::sync::mpsc::channel(4);
        manager
            .add_connection_with_sender(
                ConnectionInfo::new(id),
                Box::new(ChannelMessageSender::new(id, tx)),
            )
            .await
            .unwrap();

        let result: Result<bool, _> =
            call_client(&manager, id, "confirm", (), Duration::from_millis(10)).await;
        assert!(matches!(result, Err(BidirectionalError::Timeout)));

        // The request went out; a late answer must not find a waiting caller.
        let sent = rx.recv().await.expect("request should be sent");
        let BidirectionalMessage::Request(request) = sent.message else {
            panic!("expected the outbound request");
        };
        let late = JsonRpcResponse::success(serde_json::json!(true), request.id);
        assert!(!manager.handle_pending_response(id, late).await.unwrap());
    }
}
